# Let me try a different approach - let's look at the actual differences
inputs = ['jdu', 'cjd', 'hvfixa', 'cv', 'uuu']
outputs = ['iuddu', 'ciudd', 'bvdjxixcfjfj', 'cv', 'uuu']

print("Detailed comparison:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {outp}")
    print(f"  Length: {len(inp)} -> {len(outp)}")

    # Show character by character differences
    min_len = min(len(inp), len(outp))
    for j in range(min_len):
        if inp[j] != outp[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")

    if len(inp) != len(outp):
        if len(inp) > len(outp):
            print(f"  Extra chars in input: {inp[len(outp):]}")
        else:
            print(f"  Extra chars in output: {outp[len(inp):]}")
    print()

